INSERT INTO `Word` (`id`, `word`, `level`, `translate_en`, `translate_tr`, `translate_de`, `pronunciation_en`, `pronunciation_tr`, `pronunciation_de`, `sentence_en`, `sentence_tr`, `sentence_de`, `createdAt`, `updatedAt`) VALUES
('b8c4ed5b-176c-4566-834e-6cc002484903', 'abrupt', 'C1', 'sudden, unexpected', 'ani, beklenmedik', 'plötzlich, unerwartet', 'əˈbrʌpt', NULL, NULL, 'The meeting came to an abrupt end when the fire alarm went off.', 'Toplantı, yangın alarmı çaldığında ani bir şekilde sona erdi.', 'Die Sitzung endete abrupt, als der Feueralarm losging.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('678ab47e-a71a-4c62-aa37-d038b4a96adf', 'abundance', 'C1', 'plenty, profusion', 'bolluk, çokluk', 'Überfluss, Fülle', 'əˈbʌndəns', NULL, NULL, 'There was an abundance of food at the festival, pleasing all the attendees.', 'Festivalde bol miktarda yiyecek vardı, bu da tüm katılımcıları memnun etti.', 'Es gab eine Fülle von Essen auf dem Festival, was alle Teilnehmer erfreute.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('777c8771-7d50-4875-9e04-92fbfb140d56', 'accommodate', 'C1', 'adapt, provide for', 'uydurmak, sağlamak', 'unterbringen, anpassen', 'əˈkɒmədeɪt', NULL, NULL, 'The hotel can accommodate up to 500 guests comfortably.', 'Otel, 500 misafiri rahat bir şekilde ağırlayabilir.', 'Das Hotel kann bis zu 500 Gäste bequem unterbringen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('d107d697-9e4e-4469-99e6-59c042899ba2', 'accumulate', 'C1', 'gather, collect', 'biriktirmek, toplamak', 'ansammeln, anhäufen', 'əˈkjuːmjʊleɪt', NULL, NULL, 'Over the years, he managed to accumulate a vast collection of rare coins.', 'Yıllar içinde, nadir paraların geniş bir koleksiyonunu biriktirmeyi başardı.', 'Im Laufe der Jahre gelang es ihm, eine umfangreiche Sammlung seltener Münzen anzuhäufen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('f8fab0d2-3916-43bc-b683-bb95a7c6033d', 'acknowledge', 'C1', 'recognize, admit', 'kabul etmek, tanımak', 'anerkennen, zugestehen', 'əkˈnɒlɪdʒ', NULL, NULL, 'She refused to acknowledge the mistakes she had made in the project.', 'Projede yaptığı hataları kabul etmeyi reddetti.', 'Sie weigerte sich, die Fehler anzuerkennen, die sie im Projekt gemacht hatte.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('27cc3d59-edf8-484a-8fec-86177fa76833', 'acquire', 'C1', 'obtain, gain', 'edinmek, kazanmak', 'erwerben, gewinnen', 'əˈkwaɪə', NULL, NULL, 'He hopes to acquire new skills during his internship.', 'Stajı sırasında yeni beceriler edinmeyi umuyor.', 'Er hofft, während seines Praktikums neue Fähigkeiten zu erwerben.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('4cc2cbef-d3dd-42e1-acd8-2e96dad1069e', 'adapt', 'C1', 'adjust, modify', 'uyum sağlamak, değiştirmek', 'anpassen, modifizieren', 'əˈdæpt', NULL, NULL, 'Animals must adapt to their environment to survive.', 'Hayvanlar hayatta kalmak için çevrelerine uyum sağlamak zorundadır.', 'Tiere müssen sich an ihre Umgebung anpassen, um zu überleben.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('3720096f-c9f5-4845-98d4-9fca2388bb60', 'advocate', 'C1', 'support, promote', 'savunmak, desteklemek', 'befürworten, unterstützen', 'ˈædvəkeɪt', NULL, NULL, 'She is an advocate for environmental protection and sustainable practices.', 'Çevre koruma ve sürdürülebilir uygulamalar için bir savunucudur.', 'Sie ist eine Befürworterin des Umweltschutzes und nachhaltiger Praktiken.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('5b7bb198-c76b-4091-aa7f-9674ddb5c131', 'affiliate', 'C1', 'associate, partner', 'bağlı kuruluş, ortak', 'verbinden, Partner', 'əˈfɪlieɪt', NULL, NULL, 'The company decided to affiliate with a larger organization for better resources.', 'Şirket, daha iyi kaynaklar için daha büyük bir kuruluşla ilişki kurmaya karar verdi.', 'Das Unternehmen beschloss, sich mit einer größeren Organisation zu verbinden, um bessere Ressourcen zu erhalten.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('a29774d7-c9e4-4362-a0a7-0b3dcc314ca8', 'agenda', 'C1', 'schedule, plan', 'gündem, plan', 'Tagesordnung, Plan', 'əˈdʒɛndə', NULL, NULL, 'The agenda for the meeting included several important topics.', 'Toplantının gündemi birkaç önemli konuyu içeriyordu.', 'Die Tagesordnung für das Treffen umfasste mehrere wichtige Themen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('156c5518-0e03-43b4-b49c-71bd0a12635e', 'aggregate', 'C1', 'total, combined', 'toplam, birleştirilmiş', 'Gesamt, kombiniert', 'ˈæɡrɪɡət', NULL, NULL, 'The aggregate score of the two matches determined the winner of the tournament.', 'İki maçın toplam skoru turnuvanın kazananını belirledi.', 'Der Gesamtscore der beiden Spiele bestimmte den Gewinner des Turniers.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('93db05f0-8579-4b53-a613-22ab36bacda8', 'albeit', 'C1', 'although, even though', 'her ne kadar, olsa da', 'obwohl, auch wenn', 'ɔːlˈbiːɪt', NULL, NULL, 'The project was successful, albeit behind schedule.', 'Proje başarılıydı, olsa da zamanında tamamlanmadı.', 'Das Projekt war erfolgreich, obwohl es hinter dem Zeitplan lag.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('052e6352-f211-4458-bd95-a07db7578f0b', 'allocate', 'C1', 'assign, distribute', 'tahsis etmek, dağıtmak', 'zuteilen, verteilen', 'ˈæləkeɪt', NULL, NULL, 'The manager will allocate tasks based on each team member\'s strengths.', 'Yönetici, her ekip üyesinin güçlü yönlerine göre görevleri tahsis edecektir.', 'Der Manager wird die Aufgaben basierend auf den Stärken jedes Teammitglieds zuteilen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('2a290f91-9260-47d6-b85a-e69b1a864e4e', 'ambiguous', 'C1', 'unclear, vague', 'belirsiz, muğlak', 'mehrdeutig, unklar', 'æmˈbɪɡjuəs', NULL, NULL, 'The instructions were ambiguous, leading to confusion among the participants.', 'Talimatlar belirsizdi, bu da katılımcılar arasında kafa karışıklığına yol açtı.', 'Die Anweisungen waren mehrdeutig, was zu Verwirrung unter den Teilnehmern führte.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('81123945-d372-48f7-82bc-192ad67cb667', 'amend', 'C1', 'revise, modify', 'değiştirmek, düzeltmek', 'ändern, modifizieren', 'əˈmɛnd', NULL, NULL, 'The committee decided to amend the proposal to better suit the needs of the community.', 'Komite, öneriyi topluluğun ihtiyaçlarına daha iyi uyacak şekilde değiştirmeye karar verdi.', 'Der Ausschuss beschloss, den Vorschlag zu ändern, um besser auf die Bedürfnisse der Gemeinschaft einzugehen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('552411b8-b508-473c-8236-a80e054221db', 'analogy', 'C1', 'comparison, similarity', 'benzerlik, kıyas', 'Analogie, Vergleich', 'əˈnælədʒi', NULL, NULL, 'He used an analogy to explain the complex concept in simpler terms.', 'Karmaşık kavramı daha basit terimlerle açıklamak için bir benzetme kullandı.', 'Er benutzte eine Analogie, um das komplexe Konzept in einfacheren Begriffen zu erklären.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('1577c61d-aa2d-4eb5-ba5f-168db0ac3e2d', 'animate', 'C1', 'bring to life, energize', 'canlandırmak, hareketlendirmek', 'beleben, animieren', 'ˈænɪmeɪt', NULL, NULL, 'The artist used vibrant colors to animate the painting.', 'Sanatçı, resmi canlandırmak için canlı renkler kullandı.', 'Der Künstler verwendete lebendige Farben, um das Gemälde zu beleben.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('fd5c3e91-383f-4c90-b2a8-882df25c957d', 'anticipate', 'C1', 'expect, foresee', 'beklemek, öngörmek', 'erwarten, voraussehen', 'ænˈtɪsɪpeɪt', NULL, NULL, 'We anticipate that the project will be completed by the end of the month.', 'Projenin ay sonuna kadar tamamlanmasını bekliyoruz.', 'Wir erwarten, dass das Projekt bis Ende des Monats abgeschlossen sein wird.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('85a74210-9b6c-4ad3-9104-cf35237d0a83', 'appendix', 'C1', 'attachment, supplement', 'ek, ilave', 'Anhang, Ergänzung', 'əˈpɛndɪks', NULL, NULL, 'The report included an appendix with additional data and charts.', 'Rapor, ek olarak ek veriler ve grafikler içeren bir ek içeriyordu.', 'Der Bericht enthielt einen Anhang mit zusätzlichen Daten und Diagrammen.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('1592d3e6-d02b-4d04-90aa-90e893d5db77', 'appreciate', 'C1', 'value, recognize', 'değer vermek, takdir etmek', 'schätzen, anerkennen', 'əˈpriːʃieɪt', NULL, NULL, 'I really appreciate your help with the project; it made a significant difference.', 'Projeye yardımınız için gerçekten minnettarım; bu önemli bir fark yarattı.', 'Ich schätze Ihre Hilfe bei dem Projekt wirklich; sie hat einen erheblichen Unterschied gemacht.', '2026-07-29 15:11:48', '2026-07-29 15:11:48'),
('2578f1d0-68d9-45b4-b459-37f1012fe851', 'aspire', 'C1', 'desire, aim, hope', 'hedeflemek, istemek, umut etmek', 'streben, zielen, hoffen', 'əˈspaɪər', NULL, NULL, 'Many students aspire to achieve their dreams through hard work and dedication.', 'Birçok öğrenci, sıkı çalışma ve özveri ile hayallerine ulaşmayı hedefler.', 'Viele Studenten streben danach, ihre Träume durch harte Arbeit und Hingabe zu verwirklichen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('ca52f894-3a30-4c5b-a17c-d88b874c78d5', 'assemble', 'C1', 'gather, collect, put together', 'bir araya getirmek, toplamak, birleştirmek', 'versammeln, zusammenstellen, montieren', 'əˈsɛmbl', NULL, NULL, 'The team will assemble at the conference room to discuss the project.', 'Ekip, projeyi tartışmak için konferans odasında bir araya gelecek.', 'Das Team wird sich im Konferenzraum versammeln, um das Projekt zu besprechen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('79740309-efd7-4d72-95cf-b8c869fe2251', 'assert', 'C1', 'declare, affirm, maintain', 'belirtmek, iddia etmek, savunmak', 'behaupten, erklären, aufrechterhalten', 'əˈsɜrt', NULL, NULL, 'She decided to assert her rights during the negotiation process.', 'Müzakere sürecinde haklarını savunmaya karar verdi.', 'Sie beschloss, ihre Rechte während des Verhandlungsprozesses zu behaupten.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('a0146a40-78bf-42f3-87f4-1fe49837c681', 'assess', 'C1', 'evaluate, appraise, estimate', 'değerlendirmek, ölçmek, tahmin etmek', 'bewerten, einschätzen, beurteilen', 'əˈsɛs', NULL, NULL, 'The teacher will assess the students\' progress at the end of the term.', 'Öğretmen, dönem sonunda öğrencilerin ilerlemesini değerlendirecek.', 'Die Lehrerin wird den Fortschritt der Schüler am Ende des Semesters bewerten.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('8396fda1-ae76-4b19-9301-318a329d3bcf', 'assign', 'C1', 'allocate, designate, appoint', 'atamak, belirlemek, tayin etmek', 'zuweisen, ernennen, beauftragen', 'əˈsaɪn', NULL, NULL, 'The manager will assign tasks to each team member based on their strengths.', 'Yönetici, her takım üyesine güçlü yanlarına göre görevler atayacak.', 'Der Manager wird jedem Teammitglied Aufgaben basierend auf ihren Stärken zuweisen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('d4eb68d7-6372-440d-8dc2-b5990f2d599e', 'assure', 'C1', 'guarantee, promise, ensure', 'garanti etmek, temin etmek, güvence vermek', 'versichern, garantieren, zusichern', 'əˈʃʊr', NULL, NULL, 'I assure you that your concerns will be addressed promptly.', 'Endişelerinizin zamanında ele alınacağından sizi temin ederim.', 'Ich versichere Ihnen, dass Ihre Bedenken umgehend behandelt werden.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('a96a081c-52ae-4207-a2e2-d455166822d3', 'attach', 'C1', 'fasten, connect, join', 'bağlamak, eklemek, birleştirmek', 'befestigen, verbinden, anhängen', 'əˈtæʧ', NULL, NULL, 'Please attach the document to your email before sending it.', 'Lütfen belgeyi e-postanıza göndermeden önce ekleyin.', 'Bitte fügen Sie das Dokument Ihrer E-Mail bei, bevor Sie es senden.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('35f21194-3cc3-4e21-b302-1c7210eef28a', 'attain', 'C1', 'achieve, reach, accomplish', 'ulaşmak, başarmak, elde etmek', 'erreichen, erzielen, erreichen', 'əˈteɪn', NULL, NULL, 'She worked hard to attain her professional goals.', 'Mesleki hedeflerine ulaşmak için çok çalıştı.', 'Sie arbeitete hart, um ihre beruflichen Ziele zu erreichen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('7640c4c1-c786-45db-abc3-cbffcae14e7b', 'attribute', 'C1', 'ascribe, credit, assign', 'atfetmek, yüklemek, nitelendirmek', 'zuschreiben, anrechnen, zuordnen', 'əˈtrɪbjuːt', NULL, NULL, 'Many people attribute their success to hard work and perseverance.', 'Birçok insan başarısını sıkı çalışmaya ve azme atfeder.', 'Viele Menschen schreiben ihren Erfolg harter Arbeit und Durchhaltevermögen zu.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('95bcbfb6-c519-45e0-b55c-18f4ca092061', 'authentic', 'C1', 'genuine, real, true', 'gerçek, sahici, özgün', 'authentisch, echt, wahr', 'ɔːˈθɛntɪk', NULL, NULL, 'The museum displayed an authentic artifact from the ancient civilization.', 'Müze, antik medeniyetten gerçek bir eseri sergiledi.', 'Das Museum zeigte ein authentisches Artefakt aus der antiken Zivilisation.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('3d91f887-b106-4715-9489-07657de26a8b', 'authority', 'C1', 'power, control, influence', 'otorite, yetki, güç', 'Autorität, Macht, Einfluss', 'əˈθɔrɪti', NULL, NULL, 'The committee has the authority to make final decisions regarding the project.', 'Komitenin, proje ile ilgili son kararları verme yetkisi vardır.', 'Das Komitee hat die Autorität, endgültige Entscheidungen bezüglich des Projekts zu treffen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('c535d19b-78e0-4577-8426-c2d5a3589ae4', 'automate', 'C1', 'mechanize, computerize, streamline', 'otomatikleştirmek, bilgisayarlaştırmak, düzene sokmak', 'automatisieren, computerisieren, rationalisieren', 'ˈɔːtəˌmeɪt', NULL, NULL, 'The company decided to automate its production process to improve efficiency.', 'Şirket, verimliliği artırmak için üretim sürecini otomatikleştirmeye karar verdi.', 'Das Unternehmen beschloss, seinen Produktionsprozess zu automatisieren, um die Effizienz zu steigern.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('301c94c8-9c84-401f-b613-d971f6d56f69', 'autonomous', 'C1', 'independent, self-governing, self-sufficient', 'bağımsız, özerk, kendi kendine yeten', 'autonom, unabhängig, selbstverwaltet', 'ɔːˈtɒnəməs', NULL, NULL, 'The region has been granted autonomous status by the government.', 'Bölge, hükümet tarafından özerk statü verilmiştir.', 'Die Region hat vom Staat den autonomen Status erhalten.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('38a32f4b-3867-40e8-9370-875c84197851', 'behalf', 'C1', 'interest, support, representation', 'temsil, çıkar, destek', 'Interesse, Unterstützung, Vertretung', 'bɪˈhæf', NULL, NULL, 'On behalf of the team, I would like to thank you for your support.', 'Ekip adına, desteğiniz için teşekkür etmek istiyorum.', 'Im Namen des Teams möchte ich Ihnen für Ihre Unterstützung danken.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('8a6ce8bc-0922-43a3-a08f-f704d7742dda', 'bias', 'C1', 'prejudice, favoritism, partiality', 'önyargı, kayırma, tarafgirlik', 'Vorurteil, Voreingenommenheit, Parteilichkeit', 'ˈbaɪəs', NULL, NULL, 'The study aims to eliminate any bias in the data collection process.', 'Araştırma, veri toplama sürecindeki herhangi bir önyargıyı ortadan kaldırmayı hedefliyor.', 'Die Studie zielt darauf ab, jede Voreingenommenheit im Datenbeschaffungsprozess zu beseitigen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('5cfc0de2-df86-4e5f-87e8-9542b932aa69', 'bond', 'C1', 'connection, link, relationship', 'bağ, ilişki, bağlantı', 'Bindung, Verbindung, Beziehung', 'bɒnd', NULL, NULL, 'There is a strong bond between the mother and her child.', 'Anne ile çocuğu arasında güçlü bir bağ vardır.', 'Es gibt eine starke Bindung zwischen der Mutter und ihrem Kind.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('b387536f-7c66-4ca2-9b0e-c94cbaf4bcdb', 'bulk', 'C1', 'mass, volume, size', 'hacim, kütle, boyut', 'Masse, Volumen, Größe', 'bʌlk', NULL, NULL, 'The bulk of the work is completed, but some tasks remain.', 'İşin büyük kısmı tamamlandı, ancak bazı görevler kaldı.', 'Der Großteil der Arbeit ist abgeschlossen, aber einige Aufgaben bleiben.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('9a72adc2-56f1-4f83-9a25-eb28b1d13cc6', 'capacity', 'C1', 'ability, capability, volume', 'kapasite, yetenek, hacim', 'Kapazität, Fähigkeit, Volumen', 'kəˈpæsɪti', NULL, NULL, 'The stadium has a seating capacity of 50,000 spectators.', 'Stadyumun 50.000 seyirci kapasiteli oturma alanı vardır.', 'Das Stadion hat eine Sitzkapazität von 50.000 Zuschauern.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('d2fc8fcf-8678-428a-bf55-3f7cdc0c1e5a', 'category', 'C1', 'class, group, type', 'kategori, sınıf, grup', 'Kategorie, Klasse, Gruppe', 'ˈkætəɡəri', NULL, NULL, 'Please select the appropriate category for your submission.', 'Lütfen gönderiminiz için uygun kategoriyi seçin.', 'Bitte wählen Sie die passende Kategorie für Ihre Einreichung.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('cdeaaa3d-7d1a-4fdb-8803-1a34e4097a85', 'cease', 'C1', 'stop, halt, discontinue', 'durmak, sona ermek, kesmek', 'aufhören, stoppen, einstellen', 'siːs', NULL, NULL, 'The company will cease operations at the end of the month.', 'Şirket ayın sonunda faaliyetlerini durduracak.', 'Das Unternehmen wird seine Aktivitäten am Ende des Monats einstellen.', '2026-07-29 15:12:23', '2026-07-29 15:12:23'),
('e8fc1320-2742-45e7-ae4b-c1b667986efa', 'challenge', 'C1', 'test, obstacle, difficulty', 'zorluk, engel, meydan okuma', 'Herausforderung, Schwierigkeit, Test', 'ˈtʃælɪndʒ', NULL, NULL, 'She accepted the challenge to climb the mountain.', 'Dağı tırmanma zorluğunu kabul etti.', 'Sie nahm die Herausforderung an, den Berg zu besteigen.', '2026-07-29 15:12:54', '2026-07-29 15:12:54'),
('d3d2bb82-aa25-456a-bb58-64e29a5dc044', 'channel', 'C1', 'route, pathway, medium', 'kanal, yol, ortam', 'Kanal, Weg, Medium', 'ˈtʃænəl', NULL, NULL, 'They decided to channel their efforts into community service.', 'Çabalarını topluma hizmete yönlendirmeye karar verdiler.', 'Sie beschlossen, ihre Bemühungen in den Dienst der Gemeinschaft zu lenken.', '2026-07-29 15:12:54', '2026-07-29 15:12:54'),
('d9939c74-3667-4413-9b59-00c981583eb0', 'chapter', 'C1', 'section, phase, segment', 'bölüm, evre, kısım', 'Kapitel, Abschnitt, Phase', 'ˈtʃæptər', NULL, NULL, 'This chapter of the book discusses the impact of technology.', 'Kitabın bu bölümü teknolojinin etkisini tartışıyor.', 'Dieses Kapitel des Buches behandelt die Auswirkungen der Technologie.', '2026-07-29 15:12:54', '2026-07-29 15:12:54'),
